import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"杰夫·科门特","description":"","frontmatter":{"title":"杰夫·科门特","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/杰夫·科门特.md","filePath":"04_people/杰夫·科门特.md"}'),l={name:"04_people/杰夫·科门特.md"};function n(i,e,s,_,m,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="杰夫·科门特-jeff-comment" tabindex="-1">杰夫·科门特（Jeff Comment） <a class="header-anchor" href="#杰夫·科门特-jeff-comment" aria-label="Permalink to &quot;杰夫·科门特（Jeff Comment）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：赫尔兹伯格钻石店（Helzberg&#39;s Diamonds）CEO</li><li><strong>与巴菲特关系</strong>：伯克希尔收购后继任赫尔兹伯格CEO，负责公司日常运营</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>杰夫·科门特是赫尔兹伯格钻石店在伯克希尔·哈撒韦收购后的核心领导者。1995年小巴内特·赫尔兹伯格将家族企业出售给伯克希尔后，科门特接手担任CEO，成为伯克希尔零售业务板块的重要管理者。赫尔兹伯格钻石店在被伯克希尔收购后，继续保持独立运营模式，科门特在传承品牌历史的同时，推动公司在数字时代的转型与升级。在他的领导下，赫尔兹伯格应对了珠宝行业面临的电商冲击和消费者习惯变化，持续提升客户体验和服务质量。科门特的领导风格务实稳健，注重企业文化的延续，与巴菲特所欣赏的&quot;有品质的人&quot;标准高度一致。赫尔兹伯格钻石店在科门特的带领下，成为伯克希尔旗下最具稳定性的零售业务之一。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1995年</strong>：伯克希尔收购赫尔兹伯格钻石店后，杰夫·科门特被任命为CEO</li><li><strong>1995年后</strong>：在伯克希尔旗下持续经营赫尔兹伯格，维护品牌声誉与运营稳定</li></ul><hr><p><em>本档案基于公开信息整理，伯克希尔知识库</em></p>',8)])])}const f=t(l,[["render",n]]);export{p as __pageData,f as default};
